contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address a) internal {
        uint256 balA0;
        try c.balances(a) returns (uint256 __r) { balA0 = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        try c.withdraw() {} catch { return; }
        try c.withdraw() {} catch { return; }
        assertTrue(address(c).balance == ethBefore && c.balances(a) == balA0);
    }

    function testFuzz_run(address a) public {
